This is starting to get a bit convoluted. I'd suggest refactoring to something like that:
```python
if env.editor_build:
    unsupported_opts = []
    for disable_opt in ["disable_3d", "disable_advanced_gui", "disable_physics_2d", "disable_physics_3d"]:
        if env[disable_opt]:
            unsupported_opts.append(disable_opt)
    if unsupported_opts != []:
        print_error("The following build option(s) cannot be used for editor builds, but only for export template builds: {}.".format(", ".join(unsupported_opts)))
        Exit(255)

if env["disable_3d"]:
    env.Append(CPPDEFINES=["_3D_DISABLED"])
    env["disable_physics_3d"] = True
    env["disable_xr"] = True
if env["disable_advanced_gui"]:
    env.Append(CPPDEFINES=["ADVANCED_GUI_DISABLED"])

etc.
```

